input.command:
cd /tmp
duckdb -c "
LOAD spatial;
SELECT tier, count(*) n FROM read_parquet('/tmp/facilities.parquet') GROUP BY tier ORDER BY tier;
SELECT '---' as sep;
SELECT count(*) n_rows FROM read_parquet('/tmp/trazo_goias.parquet');
"

cd /workspace
duckdb /tmp/work.db -c "
INSTALL spatial; LOAD spatial;
CREATE OR REPLACE TABLE list AS SELECT DISTINCT cod_imovel, municipio AS list_municipio, cod_estado FROM read_csv('lists/goias-sample.csv', header=true);
CREATE OR REPLACE TABLE parcels AS
  SELECT cod_tema, nom_tema, cod_imovel, mod_fiscal, num_area, ind_status, ind_tipo, des_condic,
         municipio, cod_estado, dat_criaca, dat_atuali,
         ST_GeomFromWKB(geom_wkb) AS geom
  FROM read_parquet('/tmp/resolved_parcels.parquet');
SELECT count(*) parcels, count(distinct cod_imovel) ids FROM parcels;
-- q05
SELECT (SELECT count(*) FROM list) list_ids,
       (SELECT count(DISTINCT cod_imovel) FROM parcels WHERE cod_imovel IN (SELECT cod_imovel FROM list)) found,
       (SELECT count(*) FROM list WHERE cod_imovel NOT IN (SELECT cod_imovel FROM parcels)) missing;
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
-- q06: resolved parcels per municipio (CAR municipio)
SELECT municipio, count(*) n_parcels FROM parcels GROUP BY municipio ORDER BY municipio;
SELECT '--- compare list municipio ---' s;
SELECT list_municipio, count(*) FROM list GROUP BY 1 ORDER BY 1;
SELECT '--- q07 ---' s;
SELECT (SELECT count(*) FROM (SELECT cod_imovel FROM parcels GROUP BY cod_imovel HAVING count(*)>1)) n_dup,
       (SELECT count(*) FROM parcels WHERE num_area < 1) n_under1;
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
SELECT ST_XMin(env) xmin, ST_YMin(env) ymin, ST_XMax(env) xmax, ST_YMax(env) ymax
FROM (SELECT ST_Envelope(ST_Union_Agg(geom)) env FROM parcels);
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
-- buffered dissolved union of listed parcels (buffer 25m -> deg)
CREATE OR REPLACE TABLE parcel_union AS
SELECT ST_Union_Agg(ST_Buffer(geom, 25.0/111320.0)) AS ugeom FROM parcels;
-- field areas
CREATE OR REPLACE TABLE field_area AS
SELECT Id, ST_Area(geom) AS fa FROM fields_env;
-- per field, union fraction
CREATE OR REPLACE TABLE union_frac AS
SELECT f.Id, ST_Area(ST_Intersection(f.geom, u.ugeom)) / fa.fa AS union_frac
FROM fields_env f, parcel_union u JOIN field_area fa ON true
WHERE fa.Id = f.Id;
SELECT count(*) FROM union_frac;
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
-- fields passing union test among ALL envelope fields
SELECT count(*) FILTER (WHERE union_frac>=0.667) AS union_pass_all_envfields FROM union_frac;
-- of those, how many intersect an actual parcel?
SELECT count(*) AS union_pass_and_touch_parcel
FROM union_frac uf WHERE uf.union_frac>=0.667 AND uf.Id IN (SELECT field_id FROM field_parcel WHERE frac>0);
-- excluded = intersect a parcel but fail both
SELECT (SELECT count(distinct field_id) FROM field_parcel WHERE frac>0) - (SELECT count(*) FROM matched) AS n_excluded;
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
CREATE OR REPLACE TABLE geomcheck AS SELECT fp.field_id, fe.geom FROM field_primary fp JOIN fields_env fe ON fe.Id=fp.field_id;
-- default (assumes lat,lon)
SELECT sum(ST_Area_Spheroid(geom))/10000.0 AS spheroid_default FROM geomcheck;
SET geometry_always_xy = true;
SELECT sum(ST_Area_Spheroid(geom))/10000.0 AS spheroid_xy FROM geomcheck;
-- equal-area projection EPSG:5880
SELECT sum(ST_Area(ST_Transform(geom,'EPSG:4326','EPSG:5880')))/10000.0 AS area_5880 FROM geomcheck;
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
COPY (SELECT cod_imovel, count(*) n_fields FROM mf GROUP BY cod_imovel ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO '/tmp/q13.csv' (HEADER, DELIMITER ',');
" && cat /tmp/q13.csv

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial;
SELECT mbmode24, count(*) n_fields, sum(area_ha) area_ha, sum(d2124) post2020_ha FROM mf GROUP BY mbmode24 ORDER BY mbmode24;
"

cd /tmp
duckdb -c "
LOAD spatial;
SELECT tier, entity_kind, basis, count(*) n, min(weight) minw, max(weight) maxw FROM read_parquet('/tmp/facilities.parquet') GROUP BY 1,2,3 ORDER BY 1,2;
SELECT '--- membership entity_id samples ---' s;
SELECT entity_id, entity_kind, weight, ST_GeometryType(geometry) gt FROM read_parquet('/tmp/facilities.parquet') WHERE tier='membership_muni' AND entity_id IN ('5207600','5212204','5219258');
"

cd /workspace
duckdb /tmp/work.db -c "
LOAD spatial; SET geometry_always_xy=true;
-- q29
COPY (SELECT sum(widened) n_widened, sum(no_match) n_no_match, sum(proximity_override) n_nearest_by_far
      FROM read_csv('/tmp/q28.csv',header=true)) TO '/tmp/q29.csv' (HEADER,DELIMITER ',');
-- top candidate per cadaster
CREATE OR REPLACE TABLE top1 AS SELECT * FROM cand_kept WHERE rnk=1;
-- q30
COPY (
 SELECT fg.cod_imovel, fg.dom_annex1 AS annex1_commodity, fg.inscope_post2020 AS post2020_loss_ha,
        t.entity_id, t.entity_kind, t.tier, t.basis, t.distance_km
 FROM flagged_geom fg JOIN top1 t ON t.cod_imovel=fg.cod_imovel ORDER BY fg.cod_imovel
) TO '/tmp/q30.csv' (HEADER,DELIMITER ',', NULLSTR '');
-- workflow.csv
COPY (
 SELECT fg.cod_imovel, fg.dom_annex1 AS annex1_commodity, fg.inscope_post2020 AS post2020_loss_ha,
        t.entity_id AS top_contact_entity_id, t.entity_kind, t.tier, t.basis, t.distance_km
 FROM flagged_geom fg JOIN top1 t ON t.cod_imovel=fg.cod_imovel ORDER BY fg.cod_imovel
) TO '/tmp/workflow.csv' (HEADER,DELIMITER ',', NULLSTR '');
"
echo "=q29="; cat /tmp/q29.csv; echo "=q30="; cat /tmp/q30.csv; echo "=workflow="; cat /tmp/workflow.csv
